declarations:
export interface Hud {
  /** Register an icon and retain its handle for event-driven updates.
   * @param spec - Item definition, l10n label and optional initial values.
   * @returns Handle, inactive when UI Kit or HUD is disabled.
   * @example
   * const item = sdk.hud.register({ id: 'daily', icon: 'gift', label: 'sdk.hud.daily-rewards' });
   * item.setTimer(sdk.time.now() + 60000);
   * item.setBadge({ kind: 'dot' });
   * item.dispose();
   */
  register(spec: HudItemSpec): HudHandle;
  /** Read the active context with layout applied.
   * @returns Registered items, including hidden items.
   * @example
   * const items = sdk.hud.items();
   */
  items(): readonly HudItem[];
  /** Read visible icons in a side column.
   * @param slot - Left or right side of the screen.
   * @returns Visible items in display order.
   * @example
   * for (const item of sdk.hud.slot('right')) draw(item);
   */
  slot(slot: HudSlot): readonly HudItem[];
  /** Dispatch the registered click callback and hud:item:opened.
   * @param id - Item in the active context.
   * @example
   * sdk.hud.open('daily');
   */
  open(id: string): void;
}

export interface HudBadgeInput {
  /** Marker or bounded counter; a count of zero clears it. */
  readonly kind: HudBadgeKind;
  /** Integer 0…999999 for a count badge. */
  readonly value?: number;
}

export interface HudChanged {
  /** IDs of affected icons, bounded by the registry limit. */
  readonly ids: readonly string[];
  /** Registration, value, badge, timer, state, layout, clock tick or reset. */
  readonly reason: HudChangeReason;
}

export interface HudClient {
  register(spec: HudItemSpec): boolean;
  unregister(id: string): void;
  setValue(id: string, value: HudValue): void;
  setBadge(id: string, badge: HudBadgeInput | null): void;
  setTimer(id: string, endsAt: number | null): void;
  setProgress(id: string, progress: number | null): void;
  setState(id: string, state: HudItemState): void;
  items(): readonly HudItem[];
  open(id: string): void;
  onChange(listener: (change: HudChanged) => void): () => void;
  onOpen(listener: (id: string) => void): () => void;
  relayout(): void;
}

export interface HudHandle {
  /** Whether registration succeeded; false after disposal. */
  readonly active: boolean;
  /** Update the finite safe number or short text. */
  setValue(value: HudValue): void;
  /** Replace the notification; null clears it. */
  setBadge(badge: HudBadgeInput | null): void;
  /** Set a server epoch deadline; null clears it. */
  setTimer(endsAt: number | null): void;
  /** Set a fraction 0…1; null clears it. */
  setProgress(progress: number | null): void;
  /** Update the interaction state. */
  setState(state: HudItemState): void;
  /** Remove this registration; repeated calls are harmless. */
  dispose(): void;
}

export interface HudItem {
  /** Unique item id. */
  readonly id: string;
  /** Icon name of the theme. */
  readonly icon: string;
  /** `sdk.l10n` key of the label (also the accessible name). */
  readonly label: string;
  /** Inline label per locale from the layout (`label.values`); wins over the l10n key. */
  readonly labels?: Readonly<Record<string, string>>;
  /** Slot the item is shown in: `left` or `right`. */
  readonly slot: HudSlot;
  /** Position in the slot after the layout is applied (smaller first, then by id). */
  readonly order: number;
  /** False: hidden by the layout (visibility or filters of the player's segments). */
  readonly visible: boolean;
  /** Module id that registered the item, `game` for `sdk.hud.register`. */
  readonly owner: string;
  /** Current notification badge, independently of the countdown. */
  readonly badge?: HudBadge;
  /** Value rendered next to the icon. */
  readonly value?: HudValue;
  /** Countdown independent of the notification badge. */
  readonly timer?: HudTimer;
  /** Progress 0…1; absent when the item has none. */
  readonly progress?: number;
  /** `active` or `locked`. */
  readonly state: HudItemState;
}

export interface HudItems {
  setValue(id: string, value: HudValue): void;
  setBadge(id: string, badge: HudBadgeInput | null): void;
  setTimer(id: string, endsAt: number | null): void;
  setProgress(id: string, progress: number | null): void;
  setState(id: string, state: HudItemState): void;
  dispose(): void;
}

export interface HudItemSpec {
  /** Unique in the registry: `a-z0-9_.-`, up to 64 characters (`shop`, `daily`). */
  readonly id: string;
  /** Icon name of the theme (`shop`, `bag`, `gift`…). */
  readonly icon: string;
  /** `sdk.l10n` key of the label (also the accessible name). */
  readonly label: string;
  /** Default slot; configs layout wins. */
  readonly slot?: HudSlot;
  /** Default order in the slot (smaller first, then by id); configs layout wins. */
  readonly order?: number;
  /** Called by `hud.open(id)`; module items leave it out and the host answers `hud:item:opened`. */
  readonly onClick?: () => void;
  /** Initial short value (up to 32 characters) or finite safe number. */
  readonly value?: HudValue;
  /** Initial countdown deadline in server epoch milliseconds. */
  readonly timer?: number;
  /** Contexts in which this item appears; default main. */
  readonly contexts?: readonly string[];
  /** Initial badge of the item. */
  readonly badge?: HudBadgeInput;
  /** Opening the item (the player saw it) clears its badge. */
  readonly clearOnOpen?: boolean;
  /** Initial progress ring, 0…1 (daily streak, quest). */
  readonly progress?: number;
  /** Initial state; `locked` is drawn dimmed, opening still emits `hud:item:opened`. */
  readonly state?: HudItemState;
}

export interface HudLayout {
  readonly items: ReadonlyMap<string, HudLayoutEntry>;
  /** Items missing from `items`: shown (default) or hidden. */
  readonly unlisted: 'show' | 'hide';
}

export interface HudLayoutEntry {
  /** Side of the screen. */
  readonly slot?: HudSlot;
  /** Position in the slot (smaller first, then by id). */
  readonly order?: number;
  /** False hides the item. */
  readonly visible?: boolean;
  /** D-MATCH filter (segments, platform, A/B…); false hides the item. */
  readonly filters?: unknown;
  /** Notification shown while the module or the game has set none (static marker or counter). */
  readonly badge?: HudBadgeInput;
  /** Label (also the accessible name) instead of the label of the registration. */
  readonly label?: HudLayoutText;
  /** Icon instead of the registered one: theme icon name or module image URL. */
  readonly icon?: string;
}

export interface HudLayoutIssue {
  /** `items.<id>` for a whole entry, `items.<id>.<field>` or `unlisted`; empty for the record. */
  readonly path: string;
  /** Why the field was rejected. */
  readonly code: 'TYPE' | 'PATTERN' | 'RANGE' | 'UNKNOWN';
}

export interface HudOpened {
  /** ID of the icon opened by the player. */
  readonly id: string;
}

export interface HudTimer {
  /** Countdown deadline in server epoch milliseconds. */
  readonly endsAt: number;
  /** Remaining milliseconds measured with core.time.now(). */
  readonly remainingMs: number;
}

