declarations:
export interface Attempt<P> {
  readonly id: string; readonly seed: string; readonly playerLevel: number;
  readonly params: P; readonly startedAt: number;
}

export interface AttemptState {
  readonly active: Attempt<unknown> | null;
  readonly last: FinishedAttempt<AttemptResult> | null;
  readonly cooldownUntil: number; readonly attempts: number; readonly wins: number;
}

export interface CoreAdapter {
  currentStep(options?: MechanicCallOptions): Promise<{ n: number; stepKey: string }>;
  load(n: number, options?: MechanicCallOptions): Promise<AppliedLevel>;
  begin(applied: AppliedLevel): Promise<CoreAttempt>;
  levelEnd(attempt: CoreAttempt, result: LevelResult,
    options?: MechanicCallOptions): Promise<LevelEndAck>;
}

export interface CoreAttempt {
  /** UUID used for begin idempotency and the final levelEnd event. */
  readonly eventId: string;
  /** Server-issued hex24 ID; does not replace the action eventId. */
  readonly attemptId: string; readonly applied: AppliedLevel;
  readonly seed: string; readonly startedAt: number;
}

export interface Curve<P extends string> {
  readonly spec: CurveSpec<P>;
  readonly jsonSchema: Readonly<Record<string, unknown>>;
  validate(points: unknown): readonly CurvePoint<P>[];
  evaluate(level: number, points: readonly CurvePoint<P>[]): Readonly<Record<P, number>>;
}

export interface FinishedAttempt<R> {
  readonly attempt: Attempt<unknown>; readonly result: R;
  readonly durationMs: number; readonly finishedAt: number;
}

export interface LevelResult {
  readonly moves: number; readonly score: number; readonly won: boolean;
  readonly objectives?: readonly string[];
}

export interface LoadedCurve<P extends string> {
  readonly points: readonly CurvePoint<P>[];
  readonly record: Readonly<Record<string, unknown>>;
}

export interface MechanicAttemptFinished {
  readonly attemptId: string; readonly mode: MechanicMode;
  readonly won: boolean; readonly verified: boolean | null;
  /** Secondary reward metadata; null for core, which uses progress rewards. */
  readonly reward: number | null;
}

export interface MechanicAttemptStarted {
  readonly attemptId: string; readonly mode: MechanicMode; readonly n: number | null;
}

export interface MechanicHandle {
  readonly settings: MechanicSettings;
  ready(options?: MechanicCallOptions): Promise<MechanicMode>;
  /** Number of completed steps of settings.progressKey, including zero for a new player. */
  playerLevel(options?: MechanicCallOptions): Promise<number>;
  loadCurve<P extends string>(curve: Curve<P>,
    options?: MechanicCallOptions): Promise<LoadedCurve<P>>;
  readonly core: CoreAdapter;
  readonly attempts: SecondaryAttempts;
  dispose(): void;
}

export interface MechanicOutcome {
  readonly status: 'won' | 'lost' | 'quit' | 'cooldown' | 'error';
  readonly attemptId: string | null;
  /** Reward already issued by the mechanic, for display only. */
  readonly reward?: number;
  readonly availableAt?: number;
  readonly data?: unknown;
}

export interface MechanicSettings {
  /** Core campaign or secondary attempt. */
  readonly mode: MechanicMode;
  /** Levels set without levels. */
  readonly levelsSet: string;
  /** Progress feature containing campaign steps. */
  readonly progressKey: string;
  /** Prefix of numbered progress steps. */
  readonly stepPrefix: string;
  /** Config key in mechanic.<id>. */
  readonly curve: string;
  /** Secondary cooldown in seconds. */
  readonly cooldownSec: number;
  /** Reward weight; no reward is calculated or granted by this helper. */
  readonly rewardPercent: number;
}

export interface MechanicSettingsRecord<P extends string> {
  curve: readonly CurvePoint<P>[];
  [own: string]: unknown;
}

export interface SecondaryAttempts {
  restore(options?: MechanicCallOptions): Promise<AttemptState>;
  begin<P>(input: { playerLevel: number; params: P },
    options?: MechanicCallOptions): Promise<Attempt<P>>;
  finish<R extends AttemptResult>(attemptId: string, result: R,
    options?: MechanicCallOptions): Promise<FinishedAttempt<R>>;
  reset(options?: MechanicCallOptions): Promise<AttemptState>;
}
